  const tokens = tokenize(input);
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];

  function fail(message) {
    const e = new Error(message);
    e.status = 400;
    e.code = 'search_invalid';
    throw e;
  }

