// Bookmark Manager single-page client (no build step).
const app = document.getElementById('app');
const listEl = document.getElementById('bookmark-list');
const emptyEl = document.getElementById('empty-state');
const addForm = document.getElementById('add-form');
const addAddress = document.getElementById('add-address');
const addStatus = document.getElementById('add-status');
const searchInput = document.getElementById('search-input');
const sortSelect = document.getElementById('sort-select');
const viewButtons = [...document.querySelectorAll('.view-btn')];

const editDialog = document.getElementById('edit-dialog');
const editForm = document.getElementById('edit-form');
const editFields = {
  id: null,
  title: document.getElementById('edit-title'),
  address: document.getElementById('edit-address'),
  description: document.getElementById('edit-description'),
  note: document.getElementById('edit-note'),
  tags: document.getElementById('edit-tags'),
};

let state = { view: 'normal', sort: 'newest', q: '' };

async function api(path, options) {
  const res = await fetch(path, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  });
  if (res.status === 204) return null;
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    const message = (data && data.error && data.error.message) || `Request failed (${res.status})`;
    throw new Error(message);
  }
  return data;
}

function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function bookmarkRow(b) {
  const li = document.createElement('li');
  li.className = 'bookmark';
  li.dataset.id = b.id;
  const icon = b.iconUrl ? `<img class="icon" src="${esc(b.iconUrl)}" alt="" onerror="this.style.visibility='hidden'"/>` : '<div class="icon"></div>';
  const tags = (b.tags || []).map((t) => `<span class="tag">#${esc(t)}</span>`).join('');
  li.innerHTML = `
    ${icon}
    <div class="body">
      <a class="title" href="${esc(b.address)}" target="_blank" rel="noopener noreferrer">${esc(b.title || b.address)}</a>
      <div class="addr">${esc(b.address)}</div>
      ${b.description ? `<div class="desc">${esc(b.description)}</div>` : ''}
      <div class="tags">${tags}</div>
    </div>
    <div class="actions">
      <button data-act="edit">Edit</button>
      <button data-act="delete">Delete</button>
    </div>`;
  return li;
}

function render(items) {
  listEl.innerHTML = '';
  if (!items.length) {
    emptyEl.hidden = false;
    emptyEl.textContent =
      state.q
        ? 'No matching bookmarks.'
        : state.view === 'archived'
        ? 'No archived bookmarks.'
        : state.view === 'unread'
        ? 'Nothing unread — you are all caught up.'
        : 'No bookmarks yet. Paste a web address above to save your first one.';
    return;
  }
  emptyEl.hidden = true;
  const frag = document.createDocumentFragment();
  items.forEach((b) => frag.appendChild(bookmarkRow(b)));
  listEl.appendChild(frag);
}

async function refresh() {
  let data;
  if (state.q.trim()) {
    const params = new URLSearchParams({ q: state.q, sort: state.sort, view: state.view === 'archived' ? 'normal' : state.view });
    data = await api(`/api/search?${params}`);
  } else {
    const params = new URLSearchParams({ sort: state.sort, view: state.view });
    data = await api(`/api/bookmarks?${params}`);
  }
  render(data.items);
}

// --- Add bookmark (US1) ---
addForm.addEventListener('submit', async (e) => {
  e.preventDefault();
  addStatus.className = 'status';
  addStatus.textContent = 'Saving…';
  try {
    const data = await api('/api/bookmarks', { method: 'POST', body: JSON.stringify({ address: addAddress.value }) });
    if (data.existing) {
      addStatus.className = 'status ok';
      addStatus.textContent = 'You already saved that — opening it for editing.';
      openEdit(data.bookmark);
    } else {
      addStatus.className = 'status ok';
      addStatus.textContent = 'Saved.';
      addAddress.value = '';
    }
    await refresh();
  } catch (err) {
    addStatus.className = 'status error';
    addStatus.textContent = err.message;
  }
});

// --- Search / sort / views (US2) ---
let searchTimer;
searchInput.addEventListener('input', () => {
  clearTimeout(searchTimer);
  searchTimer = setTimeout(() => {
    state.q = searchInput.value;
    refresh().catch((err) => {
      emptyEl.hidden = false;
      emptyEl.textContent = err.message;
      listEl.innerHTML = '';
    });
  }, 200);
});
sortSelect.addEventListener('change', () => {
  state.sort = sortSelect.value;
  refresh();
});
viewButtons.forEach((btn) =>
  btn.addEventListener('click', () => {
    viewButtons.forEach((b) => b.classList.remove('active'));
    btn.classList.add('active');
    state.view = btn.dataset.view;
    refresh();
  })
);

// --- Row actions: edit / delete ---
listEl.addEventListener('click', async (e) => {
  const btn = e.target.closest('button[data-act]');
  if (!btn) return;
  const id = Number(btn.closest('.bookmark').dataset.id);
  if (btn.dataset.act === 'edit') {
    const { bookmark } = await api(`/api/bookmarks/${id}`);
    openEdit(bookmark);
  } else if (btn.dataset.act === 'delete') {
    if (!confirm('Delete this bookmark permanently?')) return;
    await api(`/api/bookmarks/${id}?confirm=true`, { method: 'DELETE' });
    await refresh();
  }
});

// --- Edit dialog ---
function openEdit(b) {
  editFields.id = b.id;
  editFields.title.value = b.title || '';
  editFields.address.value = b.address || '';
  editFields.description.value = b.description || '';
  editFields.note.value = b.note || '';
  editFields.tags.value = (b.tags || []).join(', ');
  editDialog.showModal();
}
document.getElementById('edit-cancel').addEventListener('click', () => editDialog.close());
editForm.addEventListener('submit', async (e) => {
  e.preventDefault();
  const patch = {
    title: editFields.title.value,
    address: editFields.address.value,
    description: editFields.description.value,
    note: editFields.note.value,
    tags: editFields.tags.value.split(',').map((t) => t.trim()).filter(Boolean),
  };
  try {
    await api(`/api/bookmarks/${editFields.id}`, { method: 'PATCH', body: JSON.stringify(patch) });
    editDialog.close();
    await refresh();
  } catch (err) {
    alert(err.message);
  }
});

// --- Initial load ---
(async function init() {
  try {
    await refresh();
  } catch (err) {
    emptyEl.hidden = false;
    emptyEl.textContent = 'Could not load bookmarks.';
  } finally {
    app.dataset.harnessReady = 'true';
  }
})();

