:root {
  --fg: #1a1a1a;
  --muted: #666;
  --bg: #f7f7f8;
  --card: #fff;
  --border: #e2e2e6;
  --accent: #2b6cb0;
  --font-scale: 1;
}
html[data-text-size='small'] { --font-scale: 0.9; }
html[data-text-size='medium'] { --font-scale: 1; }
html[data-text-size='large'] { --font-scale: 1.15; }

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  color: var(--fg);
  background: var(--bg);
  font-size: calc(16px * var(--font-scale));
}
#app { max-width: 900px; margin: 0 auto; padding: 1rem; }

.topbar { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; }
.topbar h1 { font-size: 1.6rem; margin: 0.5rem 0; }
.views { display: flex; gap: 0.25rem; }
.view-btn {
  border: 1px solid var(--border); background: var(--card); color: var(--muted);
  padding: 0.4rem 0.8rem; border-radius: 999px; cursor: pointer;
}
.view-btn.active { color: #fff; background: var(--accent); border-color: var(--accent); }

.add-bar { margin: 1rem 0 0.5rem; }
#add-form { display: flex; gap: 0.5rem; }
#add-address { flex: 1; padding: 0.6rem 0.8rem; border: 1px solid var(--border); border-radius: 8px; }
#add-form button, .search-bar select {
  padding: 0.6rem 1rem; border: 1px solid var(--accent); background: var(--accent);
  color: #fff; border-radius: 8px; cursor: pointer;
}
.status { min-height: 1.2rem; font-size: 0.9rem; margin-top: 0.35rem; }
.status.error { color: #c0392b; }
.status.ok { color: #2e7d32; }

.search-bar { display: flex; gap: 0.5rem; margin: 0.5rem 0 1rem; }
#search-input { flex: 1; padding: 0.55rem 0.8rem; border: 1px solid var(--border); border-radius: 8px; }
.search-bar select { background: var(--card); color: var(--fg); border-color: var(--border); }

.bookmark-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.6rem; }
.bookmark {
  display: flex; gap: 0.75rem; background: var(--card); border: 1px solid var(--border);
  border-radius: 10px; padding: 0.75rem; align-items: flex-start;
}
.bookmark .icon { width: 32px; height: 32px; flex: 0 0 32px; border-radius: 6px; object-fit: cover; background: #eee; }
.bookmark .body { flex: 1; min-width: 0; }
.bookmark .title { font-weight: 600; text-decoration: none; color: var(--fg); }
.bookmark .title:hover { color: var(--accent); }
.bookmark .addr { color: var(--muted); font-size: 0.82rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bookmark .desc { color: #333; font-size: 0.92rem; margin: 0.25rem 0; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.bookmark .tags { display: flex; flex-wrap: wrap; gap: 0.3rem; margin-top: 0.35rem; }
.tag { background: #eef3fb; color: var(--accent); border-radius: 999px; padding: 0.1rem 0.55rem; font-size: 0.78rem; }
.bookmark .actions { display: flex; flex-direction: column; gap: 0.3rem; }
.bookmark .actions button { font-size: 0.8rem; padding: 0.25rem 0.5rem; border: 1px solid var(--border); background: #fafafa; border-radius: 6px; cursor: pointer; }

.empty { text-align: center; color: var(--muted); padding: 3rem 1rem; }

dialog { border: none; border-radius: 12px; padding: 1.25rem; width: min(520px, 92vw); }
dialog h2 { margin-top: 0; }
#edit-form label { display: block; margin: 0.6rem 0; font-size: 0.9rem; color: var(--muted); }
#edit-form input, #edit-form textarea { width: 100%; padding: 0.5rem; border: 1px solid var(--border); border-radius: 6px; font: inherit; }
dialog menu { display: flex; justify-content: flex-end; gap: 0.5rem; padding: 0; margin-top: 1rem; }
dialog menu button { padding: 0.45rem 1rem; border-radius: 6px; border: 1px solid var(--border); cursor: pointer; }
#edit-save { background: var(--accent); color: #fff; border-color: var(--accent); }

